begin;
create function pg_temp.ok(v boolean,label text) returns void language plpgsql as $$begin if v is distinct from true then raise exception 'FAILED: %',label;end if;end$$;
create function pg_temp.denied(q text) returns void language plpgsql as $$begin begin execute q;exception when insufficient_privilege or raise_exception or serialization_failure or check_violation then return;end;raise exception 'UNEXPECTEDLY ALLOWED: %',q;end$$;
insert into auth.users(id,email,email_confirmed_at,raw_user_meta_data) values
('fa000000-0000-4000-8000-000000000001','tender-buyer@synthetic.invalid',now(),'{}'),('fa000000-0000-4000-8000-000000000002','tender-supplier@synthetic.invalid',now(),'{}'),('fa000000-0000-4000-8000-000000000003','tender-other@synthetic.invalid',now(),'{}'),('fa000000-0000-4000-8000-000000000004','tender-staff@synthetic.invalid',now(),'{}'),('fa000000-0000-4000-8000-000000000005','tender-super@synthetic.invalid',now(),'{}');
update public.user_roles set role=case user_id when 'fa000000-0000-4000-8000-000000000002' then 'supplier' when 'fa000000-0000-4000-8000-000000000005' then 'super_admin' else 'admin' end where user_id in('fa000000-0000-4000-8000-000000000002','fa000000-0000-4000-8000-000000000004','fa000000-0000-4000-8000-000000000005');
insert into public.businesses(id,owner_id,name,division,district) values('fb000000-0000-4000-8000-000000000001','fa000000-0000-4000-8000-000000000002','Synthetic Tender Supplier','Dhaka','Dhaka');
insert into public.verification_applications(id,business_id,revision,status,business_snapshot,valid_until) select 'fc000000-0000-4000-8000-000000000001',id,1,'approved',private.verification_snapshot(b),(now() at time zone 'Asia/Dhaka')::date+30 from public.businesses b where id='fb000000-0000-4000-8000-000000000001';
update public.businesses set verified=true,verification_application_id='fc000000-0000-4000-8000-000000000001' where id='fb000000-0000-4000-8000-000000000001';
insert into public.products(id,business_id,category_id,name,name_bn,description,price,moq,stock,status,unit) values('fd000000-0000-4000-8000-000000000001','fb000000-0000-4000-8000-000000000001',(select id from public.categories limit 1),'Synthetic Tender Product','','Only synthetic tests, rolled back',100,5,1000,'approved','piece');
create temp table tf(tid uuid,bid uuid,result jsonb,sku uuid default null);grant all on tf to authenticated;grant select on tf to anon;
set local role authenticated;set local request.jwt.claims='{"sub":"fa000000-0000-4000-8000-000000000001","role":"authenticated"}';
insert into tf(tid) select public.tender_create(jsonb_build_object('title','Synthetic supply tender','requirements','Synthetic supply requirements for rolled-back testing only','category_id',(select category_id from public.products where id='fd000000-0000-4000-8000-000000000001'),'quantity',10,'unit','piece','district','Dhaka','delivery_date',current_date+20,'expires_at',now()+interval '5 days'));
reset role;set local role anon;set local request.jwt.claims='{"role":"anon"}';
select pg_temp.denied(format('select public.tender_detail(%L)',tid)) from tf;
reset role;set local role authenticated;set local request.jwt.claims='{"sub":"fa000000-0000-4000-8000-000000000004","role":"authenticated"}';
select public.tender_moderate(tid,1,'approved','Synthetic approval') from tf;
select pg_temp.denied('select public.admin_financial_report(current_date,current_date)');
reset role;update tf set sku=(select id from public.product_skus where product_id='fd000000-0000-4000-8000-000000000001');set local role authenticated;set local request.jwt.claims='{"sub":"fa000000-0000-4000-8000-000000000002","role":"authenticated"}';
update tf set bid=public.tender_bid_save(tid,0,jsonb_build_object('product_id','fd000000-0000-4000-8000-000000000001','notes','Synthetic bid','preparation_min',1,'preparation_max',3,'expires_at',now()+interval '2 days','lines',jsonb_build_array(jsonb_build_object('sku_id',sku,'quantity',10,'unit_price',95))));
select pg_temp.ok(jsonb_array_length(public.tender_detail(tid)->'bids')=1,'bidder sees own bid') from tf;
set local request.jwt.claims='{"sub":"fa000000-0000-4000-8000-000000000003","role":"authenticated"}';
select pg_temp.ok(jsonb_array_length(public.tender_detail(tid)->'bids')=0,'unrelated buyer cannot see bids') from tf;
select pg_temp.denied(format('select public.tender_award(%L,1)',bid)) from tf;
set local request.jwt.claims='{"sub":"fa000000-0000-4000-8000-000000000004","role":"authenticated"}';
select pg_temp.ok(jsonb_array_length(public.tender_detail(tid)->'bids')=0,'staff cannot see sealed bid content') from tf;
set local request.jwt.claims='{"sub":"fa000000-0000-4000-8000-000000000001","role":"authenticated"}';
update tf set result=public.tender_award(bid,1);
select pg_temp.ok(public.tender_award(bid,1)=result,'award retry creates one offer') from tf;
select pg_temp.ok((public.sourcing_detail((result->>'request_id')::uuid)->>'buyer_id')=auth.uid()::text,'award enters participant-authorized offer flow') from tf;
select public.sourcing_offer_checkout((result->>'offer_id')::uuid,1,'fe000000-0000-4000-8000-000000000001','{"name":"Synthetic Receiver","phone":"01712345678","division":"Dhaka","district":"Dhaka","address":"Synthetic address, rolled back"}','cod','Synthetic tender checkout') from tf;
select public.sourcing_offer_checkout((result->>'offer_id')::uuid,1,'fe000000-0000-4000-8000-000000000001','{"name":"Synthetic Receiver","phone":"01712345678","division":"Dhaka","district":"Dhaka","address":"Synthetic address, rolled back"}','cod','Synthetic tender checkout') from tf;

reset role;
select pg_temp.ok((select count(*)=1 from public.orders where buyer_id='fa000000-0000-4000-8000-000000000001' and subtotal=950 and status='pending_confirmation'),'award checkout remains supplier-confirmed and idempotent');
select pg_temp.ok((select stock=990 from public.product_skus where product_id='fd000000-0000-4000-8000-000000000001'),'stock reserved exactly once');
select pg_temp.ok((select count(*)=1 from public.sourcing_offer_lines l,tf where l.offer_id=(tf.result->>'offer_id')::uuid and l.unit_price=95),'immutable selected bid prices transferred');
select pg_temp.ok((select count(*)=1 from public.admin_audit_logs a,tf where a.entity_id=tf.tid and a.action='tender.moderated'),'moderation audit written');
update public.sourcing_offers set accepted_order_id=null,expires_at=now()+interval '1 hour' where id in(select (result->>'offer_id')::uuid from tf);
select private.remind_expiring_offers();select private.remind_expiring_offers();
select pg_temp.ok((select count(*)=1 from public.notifications n,tf where n.entity_id=(tf.result->>'offer_id')::uuid and n.kind='quotation_response'),'offer expiry notices are deduplicated');
set local role authenticated;set local request.jwt.claims='{"sub":"fa000000-0000-4000-8000-000000000005","role":"authenticated"}';
select pg_temp.ok(jsonb_typeof(public.admin_financial_report(current_date,current_date)->'rows')='array','super admin report authorized');
reset role;select 'Tender moderation, sealed bids, award idempotency and report access checks passed' result;
rollback;
